package cn.gov.document.platform.review.api;import cn.gov.document.platform.review.domain.ReviewFalsePositiveEntity;import jakarta.validation.constraints.*;import java.time.OffsetDateTime;
public final class FalsePositiveDtos{private FalsePositiveDtos(){}public record SubmitRequest(@NotBlank @Size(max=5000)String reason){}public record ReviewRequest(@NotBlank String reviewStatus,@Size(max=5000)String optimizationSuggestion){}public record Response(String id,String issueId,String ruleId,String originalText,String suggestedFix,String reason,String submitterId,String reviewStatus,String reviewedBy,String optimizationSuggestion,int lockVersion,OffsetDateTime createdAt){public static Response from(ReviewFalsePositiveEntity e){return new Response(e.getId(),e.getIssueId(),e.getRuleId(),e.getOriginalText(),e.getSuggestedFix(),e.getReason(),e.getSubmitterId(),e.getReviewStatus(),e.getReviewedBy(),e.getOptimizationSuggestion(),e.getLockVersion(),e.getCreatedAt());}}}
